"""H validation: the support objects in the region's home-clearance check.

    MUJOCO_GL=egl python experiments/h_validate.py

1. The 20 cm raised box case of experiments/g0_raised_check.py: the stance the full check rejected for the home clearance to the box (0.775, 1.035, pedestal 0.17) must now have count zero in the region, and the
   overlay's new pick is checked with the full check.
2. The test scene's clearance of the arms at home to the hotplate at TASK_CFG's stance and at the overlay's pick (the region's number and the full check's).
"""
import math
import time

import mujoco
import numpy as np

from experiments.bench_stance_validate import scene_objects
from src import bench_stance as bs
from src.full_check import FullCheck
from src.furniture_map import FurnitureMap
from src.home_clearance_map import HomeClearanceMap
from src.task_beaker_hotplate import bench_top_z
from src.task_config import BENCH_STANCE_CFG, TASK_CFG
from src.task_points import task_points


def arm_to_box(cams, robot, stance, box):
    """Smallest distance (m) from the arms' surface points at home, for a base at stance (x, y, yaw, q), to a world box {"xy", "half", "z0", "z1"}."""
    x, y, yaw, q = stance
    c, s = math.cos(yaw), math.sin(yaw)
    P = cams["arm_pts"]
    wx, wy = x + c * P[:, 0] - s * P[:, 1], y + s * P[:, 0] + c * P[:, 1]
    wz = P[:, 2] + robot["lift_factor"] * q
    W = np.stack([wx, wy, wz], axis=-1)
    d = np.maximum(np.maximum(np.array([box["xy"][0] - box["half"][0], box["xy"][1] - box["half"][1], box["z0"]]) - W, W - np.array([box["xy"][0] + box["half"][0], box["xy"][1] + box["half"][1], box["z1"]])), 0.0)
    return float(np.sqrt((d ** 2).sum(axis=1)).min()) - 0.003


if __name__ == "__main__":
    maps = bs.load_maps("data/reach_map")
    fc = FullCheck(maps=maps)
    m, rg, chk = fc.model, fc.rg, fc.chk
    yaw = TASK_CFG["staging_yaw"]
    qs = bs.pedestal_commands()
    cams = bs.camera_poses(m, qs, chk=chk, ref_stance=(*TASK_CFG["staging_xy"], yaw), cache_dir=BENCH_STANCE_CFG["cache_dir"])
    lmaps = {k: v for k, v in maps.items() if k[0] == "left"}
    furn = FurnitureMap.from_model(m, mujoco.MjData(m), exclude_bodies=("task_beaker",))
    hcm = HomeClearanceMap(m, fc.scene_data, chk, np.array(TASK_CFG["beaker_xy"]), robot_geometry=rg, slack=0.0)
    extra = bs.make_extra_blocked(furn, rg, yaw, hcm.clear_mask)
    bench = {"yaw": yaw, "open": TASK_CFG["bench_open"]}
    top = bench_top_z(m)
    base_q = fc.chk.q_scene.copy()
    # 1. the 20 cm case
    r = 0.20
    objs = scene_objects(m, fc.scene_data, raise_m=r)
    t0 = time.perf_counter()
    res = bs.overlay(objs, lmaps, rg, cams, bench, extra, use_cache=False, say=lambda *_: None)
    print(f"1. raised 0.20 m: the overlay now picks {np.round(res['xy'], 3).tolist()} pedestal {res['q']:.2f}, covers {res['covered']}, counts {res['counts']} ({time.perf_counter() - t0:.1f} s; filter {res['seconds']['filter']:.2f} s, region {res['seconds']['region']:.1f} s)")
    X, Y = res["grid"]
    old = (0.775, 1.035, 0.17)
    iy, ix = int(np.argmin(abs(Y[:, 0] - old[1]))), int(np.argmin(abs(X[0] - old[0])))
    qi = int(np.argmin(abs(np.array(qs) - old[2])))
    print(f"   the stance the full check rejected {old}: beaker count there now {int(res['stack'][0, qi, iy, ix])} (the full check said home clearance 10 mm to the box)")
    box = objs[0]["supports"][0]
    print(f"   the region's own clearance of the arms at home to the box at that stance: {1000 * arm_to_box(cams, rg, (old[0], old[1], yaw, old[2]), box):.0f} mm")
    q = fc.chk.q_scene.copy()
    q[fc._beaker_free + 2] += r
    fc.chk.q_scene = q
    bxy = np.array(TASK_CFG["beaker_xy"], float)
    boxobj = {"id": "box", "outline": np.array([[bxy[0] - 0.06, bxy[1] - 0.06], [bxy[0] + 0.06, bxy[1] + 0.06]]), "height_range": (top, top + r)}
    pts = task_points(m, fc.scene_data)
    for p in pts:
        if p["path"] == "grasp":
            p["p"][2] += r
    for name, st in (("rejected stance", old), ("the overlay's new pick", (res["xy"][0], res["xy"][1], res["q"]))):
        fr = fc.check((st[0], st[1], yaw, st[2]), pts, objects=[boxobj], use_cache=False)
        print(f"   full check at the {name} {np.round(st, 3).tolist()}: {'PASS' if fr['ok'] else 'FAIL'} {fr['failed']} {fr['reason'][:140]}")
    fc.chk.q_scene = base_q
    fc.set_objects([])                                   # the box slot is emptied again
    # 2. the hotplate clearance in the test scene
    objs = scene_objects(m, fc.scene_data)
    res = bs.overlay(objs, lmaps, rg, cams, bench, extra, use_cache=False, say=lambda *_: None)
    hp = objs[1]["supports"][0]
    print(f"2. test scene: the overlay picks {np.round(res['xy'], 3).tolist()} pedestal {res['q']:.2f}, counts {res['counts']}")
    for name, st in (("TASK_CFG's stance", (*TASK_CFG["staging_xy"], yaw, TASK_CFG["pedestal_q"])), ("the overlay's pick", (res["xy"][0], res["xy"][1], yaw, res["q"]))):
        reg_mm = 1000 * arm_to_box(cams, rg, st, hp)
        hc = chk.home_clearance(st)
        pb = chk.beaker_on_hotplate_clearance(st)
        X, Y = res["grid"]
        iy, ix = int(np.argmin(abs(Y[:, 0] - st[1]))), int(np.argmin(abs(X[0] - st[0])))
        qi = int(np.argmin(abs(np.array(qs) - st[3])))
        print(f"   {name} {np.round(st, 3).tolist()}: arms at home to the hotplate: region {reg_mm:.0f} mm, full check's home clearance {1000 * hc['arms']:.0f} mm ({hc['arms_pair']}), placed beaker {1000 * pb:.0f} mm; counts there {[int(res['stack'][k, qi, iy, ix]) for k in range(len(objs))]}")
